def esc(s):
    s = html.escape(s, quote=False).replace("'", "\\'").replace('"', '\\"')
    if s.startswith("@") or s.startswith("?"): s = "\\" + s
    return s
base = os.path.join(os.path.dirname(os.path.abspath(__file__)), "../../android-app/app/src/main/res")
for lang, idx, d in (("es", 0, "values"), ("en", 1, "values-en")):
    os.makedirs(f"{base}/{d}", exist_ok=True)
    with open(f"{base}/{d}/strings.xml", "w") as f:
        f.write('<?xml version="1.0" encoding="utf-8"?>\n<!-- Generado desde scripts/i18n/strings.py. Idioma: %s -->\n<resources>\n' % lang)
        for k in sorted(S):
            extra = ' translatable="false"' if k == "app_name" and idx == 0 else ""
            if k == "app_name" and idx == 1: continue
            f.write(f'    <string name="{k}"{extra}>{esc(S[k][idx])}</string>\n')
        f.write("</resources>\n")
print(len(S))
